#include <bits/stdc++.h>
using namespace std;

vector<int> jobScheduling(vector<array<int, 3>>& jobs) {
    // jobs[i] = {id, deadline, profit}
    int maxDead = 0;
    for (auto& j : jobs) maxDead = max(maxDead, j[1]);
    sort(jobs.begin(), jobs.end(), [](auto& a, auto& b) { return a[2] > b[2]; });
    vector<bool> used(maxDead + 1, false);
    int count = 0, profit = 0;
    for (auto& [id, dead, pay] : jobs) {
        for (int slot = min(dead, maxDead); slot >= 1; --slot) {
            if (!used[slot]) {
                used[slot] = true;
                ++count;
                profit += pay;
                break;
            }
        }
    }
    return {count, profit};
}

