import java.util.*;

class Solution {
    public int[] jobSequencing(int[][] jobs) {  // jobs[i] = {id, deadline, profit}
        int maxDead = 0;
        for (int[] j : jobs) maxDead = Math.max(maxDead, j[1]);
        Arrays.sort(jobs, (a, b) -> b[2] - a[2]);
        boolean[] used = new boolean[maxDead + 1];
        int count = 0, profit = 0;
        for (int[] job : jobs) {
            for (int slot = Math.min(job[1], maxDead); slot >= 1; --slot) {
                if (!used[slot]) {
                    used[slot] = true;
                    ++count;
                    profit += job[2];
                    break;
                }
            }
        }
        return new int[]{count, profit};
    }
}
